  var ra := intervals[0][1];
  var i := 1;
  while i < n
    invariant 1 <= i <= n
    invariant |a| == 100
    invariant steps == 6 * i - 5
    decreases n - i
  {
    var l := intervals[i][0];
    var r := intervals[i][1];
    if 0 <= l < 100 {
      a := a[l := a[l] + 1];
    }
    if 0 <= r < 100 {
      a := a[r := a[r] - 1];
